import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Export diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/diagnostics.md","filePath":"troubleshooting/diagnostics.md","lastUpdated":1792978100000}'),i={name:"troubleshooting/diagnostics.md"};function s(n,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="export-diagnostics" tabindex="-1">Export diagnostics <a class="header-anchor" href="#export-diagnostics" aria-label="Permalink to &quot;Export diagnostics&quot;">​</a></h1><p>This page shows how to collect the information needed to look into a problem, and what that file contains.</p><h2 id="export-the-file" tabindex="-1">Export the file <a class="header-anchor" href="#export-the-file" aria-label="Permalink to &quot;Export the file&quot;">​</a></h2><ol><li>Right-click the MeetCue tray icon and choose <strong>Export diagnostics…</strong>, or open <strong>Settings › Diagnostics</strong> and click <strong>Export…</strong>.</li><li>Click <strong>Show what will be included</strong> to see the file list.</li><li>Choose where to save the zip file.</li></ol><h2 id="what-is-included" tabindex="-1">What is included <a class="header-anchor" href="#what-is-included" aria-label="Permalink to &quot;What is included&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Logs</td><td>MeetCue&#39;s log files from the last three days. API keys and tokens are masked.</td></tr><tr><td>Settings</td><td><code>settings.json</code> without briefing material text. Keys are never in this file.</td></tr><tr><td>Latency history</td><td><code>latency-history.json</code> from the latency probe.</td></tr><tr><td>System information</td><td>Windows version, MeetCue version, audio device names and sample rates.</td></tr></tbody></table><h2 id="what-is-never-included" tabindex="-1">What is never included <a class="header-anchor" href="#what-is-never-included" aria-label="Permalink to &quot;What is never included&quot;">​</a></h2><ul><li>API keys and access tokens.</li><li>Transcripts of what was said. Logs don&#39;t contain transcripts unless you turned on debug logging, and even then they aren&#39;t exported.</li><li>Briefing material and practice records.</li></ul><h2 id="run-the-self-test" tabindex="-1">Run the self-test <a class="header-anchor" href="#run-the-self-test" aria-label="Permalink to &quot;Run the self-test&quot;">​</a></h2><p><code>MeetCue.exe --self-test</code> checks the parts that are hard to test anywhere but on your computer and prints a short report:</p><ul><li>system sound capture receives a test tone (mute the speakers or wear headphones);</li><li>the microphone level;</li><li>all shortcuts register;</li><li>the panel is hidden from screenshots;</li><li>providers respond, if keys are configured.</li></ul><p>Copy the report into your issue.</p><h2 id="report-a-problem" tabindex="-1">Report a problem <a class="header-anchor" href="#report-a-problem" aria-label="Permalink to &quot;Report a problem&quot;">​</a></h2><p><a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">Open an issue</a>. The form asks for the error code, your MeetCue version (<code>MeetCue.exe --version</code>) and the steps that lead to the problem. Attach the diagnostics zip.</p><h2 id="debug-logging" tabindex="-1">Debug logging <a class="header-anchor" href="#debug-logging" aria-label="Permalink to &quot;Debug logging&quot;">​</a></h2><p>If asked, turn on <strong>Settings › Diagnostics › Debug logging</strong>, reproduce the problem and export again. Debug logging also writes transcripts to the log on your computer. Turn it off afterwards.</p>',16)])])}const g=t(i,[["render",s]]);export{p as __pageData,g as default};
